-- 0031: catálogo completo de ejercicios (126 ejercicios).
-- GENERADO por scripts/generate-exercise-sql.mjs desde src/data/exercises.ts.
-- Upsert: actualiza los existentes (incluye taxonomía de hombros front/lateral/rear_delt)
-- e inserta los nuevos.
on conflict (id) do update set
  name = excluded.name,
  muscle_group = excluded.muscle_group,
  equipment = excluded.equipment,
  is_compound = excluded.is_compound,
  instructions = excluded.instructions;
